 ruleOut=[inv("advancedImaging", "Contrast computed tomography (CT) abdomen", "CT", "Malignancy, abscess", "No mass", "Periampullary or pancreatic mass, liver abscess", "When malignancy or complications suspected; refer (ICMR STW).", "gsurg", CB)],
